// «Как проходит запись»: bold poster band right after the booking form — three numbered steps
// (choice of doctor, time, confirmation) so the patient sees the whole path up front.
// Lively: steps rise in on scroll (respects prefers-reduced-motion), bold layout without three equal cards in a row.
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";

type Step = { title: string; note: string };

export type StepsBookingOverviewProps = {
  eyebrow: string;
  title: string;
  steps: [Step, Step, Step];
};

export default function StepsBookingOverview({ eyebrow, title, steps }: StepsBookingOverviewProps) {
  const reduce = useReducedMotion();

  const rise = (i: number) =>
    reduce
      ? {}
      : {
          initial: { opacity: 0, y: 28 },
          whileInView: { opacity: 1, y: 0 },
          viewport: { once: true, amount: 0.4 },
          transition: { duration: 0.45, delay: 0.12 * i, ease: "easeOut" as const },
        };

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="max-w-text min-w-0">
          <p className="text-small font-bold tracking-wide text-primary uppercase">{eyebrow}</p>
          <h2 className="mt-2 font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
        </div>

        <LazyMotion features={domAnimation}>
          <ol className="mt-10 grid grid-cols-1 gap-6 md:grid-cols-3 md:gap-8">
            {steps.map((step, i) => (
              <m.li
                key={step.title}
                {...rise(i)}
                className={`flex min-w-0 flex-col gap-3 border-t-2 border-primary pt-6 ${
                  i === 1 ? "md:border-t-0 md:border-l-2 md:pl-8 md:pt-0" : ""
                } ${i === 2 ? "md:border-t-0 md:border-l-2 md:pl-8 md:pt-0" : ""}`}
              >
                <span className="font-display text-h1 font-bold text-primary" aria-hidden="true">
                  {String(i + 1).padStart(2, "0")}
                </span>
                <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                <p className="text-body text-muted-foreground wrap-break-word">{step.note}</p>
              </m.li>
            ))}
          </ol>
        </LazyMotion>
      </div>
    </section>
  );
}

