// «Как проходит запись»: bold poster band right after the booking form — three steps
// (choice of doctor, time, confirmation) so the patient sees the whole path up front.
// Vertical numbered rows on the right, headline block on the left (dominant composition, not a card row).
// Lively: steps rise in on scroll (respects prefers-reduced-motion), content visible without animation.
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";

type Step = { title: string; note: string };

export type StepsBookingOverviewProps = {
  eyebrow: string;
  title: string;
  steps: [Step, Step, Step];
};

export default function StepsBookingOverview({ eyebrow, title, steps }: StepsBookingOverviewProps) {
  const reduce = useReducedMotion();

  const rise = (i: number) =>
    reduce
      ? {}
      : {
          initial: { opacity: 0, x: 24 },
          whileInView: { opacity: 1, x: 0 },
          viewport: { once: true, amount: 0.5 },
          transition: { duration: 0.45, delay: 0.12 * i, ease: "easeOut" as const },
        };

  return (
    <section className="bg-card font-sans text-card-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid grid-cols-1 gap-10 lg:grid-cols-[minmax(0,2fr)_minmax(0,3fr)] lg:gap-16">
