            <ol className="flex min-w-0 flex-col">
              {steps.map((step, i) => (
                <m.li
                  key={step.title}
                  {...rise(i)}
                  className="flex min-w-0 items-start gap-6 border-b border-border py-6 first:border-t"
                >
                  <span
                    className="inline-flex min-h-11 min-w-11 shrink-0 items-center justify-center rounded-control bg-primary font-display text-h3 font-bold text-primary-foreground"
                    aria-hidden="true"
                  >
                    {i + 1}
                  </span>
                  <div className="min-w-0">
                    <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                    <p className="mt-1 text-body text-muted-foreground wrap-break-word">{step.note}</p>
                  </div>
                </m.li>
              ))}
            </ol>
          </LazyMotion>
        </div>
      </div>
    </section>
  );
}

